nui 1
const Unit: number = 5
const Delta: number = 24
const Ticks: number[] = [5,29]
module Box(Seed: number) {
const Private: point = if (@Seed > 0) { coordinate(x: @Seed + 2, y: 24) } else { coordinate(x: @Seed / 0, y: 0) }
export point Mark = from(source: @Private)
}
for Tick in @Ticks {
instance Live = Box(Seed: @Tick)
point Consumer = from(source: @Live::Mark)
}
point Survivor = coordinate(x: @Unit + @Delta, y: 0)

